package android.os;import java.util.*;public class Parcel{private List<Object> a=new ArrayList<>();private int p;public static Parcel obtain(){return new Parcel();}public void writeString(String s){a.add(s);}public void writeInt(int n){a.add(n);}public int readInt(){return (Integer)a.get(p++);}public void writeInterfaceToken(String s){writeString(s);}public void enforceInterface(String s){if(!s.equals(a.get(p++)))throw new SecurityException();}public void writeNoException(){}}